fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_width = width as usize;

    if orig_len >= target_width {
        // Original sequence is already equal or longer than target width,
        // return it unchanged.
        orig
    } else {
        // Need to pad with fillchar so that orig appears as suffix.
        let padding_len = target_width - orig_len;
        let mut result = Vec::with_capacity(target_width);

        // Fill the leading positions with fillchar
        for _ in 0..padding_len {
            result.push(fillchar);
        }

        // Append the original sequence as suffix
        result.extend(orig);

        result
    }
}